import{_ as d,p as a,q as n,s as t,R as e,t as s,Y as o,n as c}from"./framework-e1bed10d.js";const h="/my-blog/assets/038_01-d57a0208.jpg",i="/my-blog/assets/038_02-285a2b7e.png",p={},_=t("h1",{id:"借据-一笔贷款的唯一档案",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#借据-一笔贷款的唯一档案","aria-hidden":"true"},"#"),e(" 借据：一笔贷款的唯一档案")],-1),l={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484958&idx=1&sn=42c5f67068f60a395f6759df4d15188d&chksm=e8c6f662dfb17f74954bca6d26b67a76a231e8b983f5645ec941b90bf17599e31f59d3615600",target:"_blank",rel:"noopener noreferrer"},f=o('<hr><p>二、借据：一笔贷款的唯一档案</p><h3 id="一-借据上有什么" tabindex="-1"><a class="header-anchor" href="#一-借据上有什么" aria-hidden="true">#</a> （一）借据上有什么</h3><p>借据是核心系统里一笔贷款的档案。放款成功后，系统为这笔贷款生成一张借据，记录：客户、产品、合同号、贷款金额、期限、利率（正常利率、罚息利率、复息利率）、担保方式、还款方式、还款频率、放款机构与渠道、起息日与到期日。</p><p><img src="'+h+'" alt="图片"></p><p><strong>图5-6 借据：一笔贷款的唯一档案（核心要素 · 账号规则 · 状态机）</strong></p><p><strong>表5-1 借据的核心要素</strong></p><table><thead><tr><th><strong>要素</strong></th><th><strong>说明</strong></th></tr></thead><tbody><tr><td>借据号+渠道号</td><td>业务系统的借据标识，渠道号保证跨系统唯一</td></tr><tr><td>贷款账号</td><td>核心内部唯一标识一笔借据，余额明细都挂在它下面</td></tr><tr><td>客户/合同</td><td>借据归属的客户与贷款合同</td></tr><tr><td>产品</td><td>决定科目、利率、还款方式的贷款产品</td></tr><tr><td>金额与期限</td><td>放款金额、起息日、到期日</td></tr><tr><td>利率</td><td>正常利率、罚息利率、复息利率</td></tr><tr><td>还款方式</td><td>等额本息、等额本金、先息后本等</td></tr></tbody></table><h3 id="二-贷款账号的编号规则" tabindex="-1"><a class="header-anchor" href="#二-贷款账号的编号规则" aria-hidden="true">#</a> （二）贷款账号的编号规则</h3><p>比如一笔贷款账号是“2 +机构号6位+科目号13位+顺序号8位+校验位1位”，科目号对应记账科目（如正常本金），顺序号就是这笔贷款的流水号；资产转让账户则是“4 +机构号6位+科目号13位+资产号8位+校验位1位”。</p><p>为什么要把机构、科目编进账号？因为核心是“一对多”的，一个贷款账号不只要知道是哪个客户的钱，还要能直接从账号里看出它属于哪个机构、哪个科目，日终汇总、总分核对、报表输出都靠这个前缀来分组。这是把查询压力前置到编号设计上，比每次join一张机构表快得多，也稳得多。</p><h3 id="三-借据状态机" tabindex="-1"><a class="header-anchor" href="#三-借据状态机" aria-hidden="true">#</a> （三）借据状态机</h3><p>借据从生到死，要经历一系列状态。从逾期记账角度看，有：结清、未到期、展期、逾期、非应计、核销；从贷款类别看，正常、关注、次级、可疑、损失（五级分类，本章与第九章展开）。系统里的借据状态，就是这两个维度的组合，由日终批量和人工操作驱动迁移。</p><p><img src="'+i+'" alt="图片"></p><p><strong>图5-7 借据状态机：状态与迁移</strong></p><p>借据是一笔贷款的唯一档案，所有后续动作都挂在借据下面。但借据不是填完就一成不变的：放款后利率可能调整（LPR重定价）、期限可能变更（展期）、状态可能变化（正常转逾期），所以既要记录当前值，也要保留变更历史。</p>',16);function b(m,g){const r=c("ExternalLinkIcon");return a(),n("div",null,[_,t("blockquote",null,[t("p",null,[e("公众号：侃西东　·　发布日期：2026-10-24　·　"),t("a",l,[e("微信原文"),s(r)])])]),f])}const x=d(p,[["render",b],["__file","038.html.vue"]]);export{x as default};
